if (!function_exists('cmsRenderFooterSocialMedia')) {
    function cmsRenderFooterSocialMedia(array $socialLinks, array $options = []): void
    {
        $socialLinks = array_values(array_filter($socialLinks, static fn($item) => is_array($item) && !empty($item['url'])));
        if ($socialLinks === []) {
            return;
        }

        $wrapperClass = trim((string) ($options['wrapper_class'] ?? ''));
        $headingClass = trim((string) ($options['heading_class'] ?? 'md:text-[22px] text-[18px] font-[600]'));
        $listClass = trim((string) ($options['list_class'] ?? 'flex flex-wrap md:gap-4 gap-2 mt-2 md:mt-4'));
        $hoverSwap = (bool) ($options['hover_swap'] ?? true);
        $idSuffix = (string) ($options['id_suffix'] ?? '');

        ?>
        <div<?= $wrapperClass !== '' ? ' class="' . htmlspecialchars($wrapperClass, ENT_QUOTES, 'UTF-8') . '"' : '' ?>>
            <h2 class="<?= htmlspecialchars($headingClass, ENT_QUOTES, 'UTF-8') ?>" style="color:#B4D7FF">Social Media</h2>
            <ul class="<?= htmlspecialchars($listClass, ENT_QUOTES, 'UTF-8') ?>">
                <?php foreach ($socialLinks as $social):
                    $name = (string) ($social['name'] ?? '');
                    $url = (string) ($social['url'] ?? '');
                    if ($url === '') {
                        continue;
                    }
                ?>
                <li>
                    <a href="<?= htmlspecialchars($url, ENT_QUOTES, 'UTF-8') ?>" target="_blank" rel="noopener noreferrer" class="<?= $hoverSwap ? 'real-should-display transition-all' : 'transition-all' ?>" aria-label="<?= htmlspecialchars($name, ENT_QUOTES, 'UTF-8') ?>">
                        <?php cmsRenderFooterSocialIcon($name, $hoverSwap, $idSuffix); ?>
                    </a>
                </li>
                <?php endforeach; ?>
            </ul>
        </div>
        <?php
    }
}
